// ELEMENTS:
// 1. Fundo branco com o filete vermelho no topo
// 2. Eyebrow + total em grande (anim.text, ex. "3 + 5 anos"): números a azul royal e vermelho, resto navy
// 3. Linha do tempo com um bloco por ano: os anos do 1.º período (items "3: isenção") enchem-se a azul
//    royal um a um, os do 2.º a vermelho; legenda colorida por baixo de cada período
// 4. Sub em cinzento
import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const TINT = "#E8EEF9";
const LINEL = "#D5DCE8";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const GREY = "#5A6370";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(2));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const SEG = [BLUE, RED, NAVY];

const LinhaTempoAnos: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? "").trim();
  const sub = String(p.sub ?? "").trim();
  const text = String(anim.text ?? "").trim();
  const segs = (Array.isArray(p.items) ? (p.items as unknown[]).map(String) : []).map((s) => {
    const i = s.indexOf(":");
    return { n: Math.max(1, parseInt(i > 0 ? s.slice(0, i) : s, 10) || 1), label: i > 0 ? s.slice(i + 1).trim() : "" };
  }).slice(0, 3);
  const total = Math.max(1, segs.reduce((a, s) => a + s.n, 0));

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const trackW = 920 * u;
  const gap = 12 * u;
  const blockW = (trackW - gap * (total - 1)) / total;
  let numIdx = 0;
  const parts = text.split(/(\d+)/).filter(Boolean);

  // Year k belongs to segment s; segment s starts filling at 0.8 + s*1.4 s, one year every 0.16 s.
  const yearSeg: number[] = [];
  segs.forEach((s, i) => { for (let k = 0; k < s.n; k++) yearSeg.push(i); });
  const yearAt = (k: number) => {
    const s = yearSeg[k];
    const first = yearSeg.indexOf(s);
    return 0.8 + s * 1.4 + (k - first) * 0.16;
  };

  return (
    <AbsoluteFill style={{ backgroundColor: WHITE, overflow: "hidden" }}>
      <AbsoluteFill style={{ backgroundImage: `linear-gradient(${TINT} ${2 * u}px, transparent ${2 * u}px), linear-gradient(90deg, ${TINT} ${2 * u}px, transparent ${2 * u}px)`, backgroundSize: `${60 * u}px ${60 * u}px`, opacity: 0.7 }} />
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", flexDirection: "column", gap: 70 * u }}>
        {eyebrow ? (
          <div style={{ display: "flex", alignItems: "center", gap: 18 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: BLUE, opacity: show(0.05) }}>
            <div style={{ width: 44 * u, height: 3 * u, background: RED }} />
            {eyebrow}
          </div>
        ) : null}
        <div style={{ fontFamily: FONTS.display, fontSize: 180 * u, lineHeight: 1, color: NAVY, whiteSpace: "nowrap", opacity: show(0.1), transform: `translateY(${(1 - show(0.1)) * 26 * u}px)` }}>
          {parts.map((s, i) => {
            const isNum = /\d/.test(s);
            const col = isNum ? SEG[numIdx++ % SEG.length] : NAVY;
            return <span key={i} style={{ fontWeight: isNum ? 800 : 300, color: col }}>{s}</span>;
          })}
        </div>
        <div style={{ display: "flex", flexDirection: "column", gap: 22 * u }}>
          <div style={{ display: "flex", gap }}>
            {Array.from({ length: total }, (_, k) => {
              const s = yearSeg[k];
              const on = show(yearAt(k), 0.35, BACK);
              const col = SEG[s % SEG.length];
              return (
                <div key={k} style={{ position: "relative", width: blockW, height: 150 * u, borderRadius: 18 * u, border: `${2 * u}px solid ${LINEL}`, boxSizing: "border-box", background: TINT, overflow: "hidden", opacity: show(0.3 + k * 0.04, 0.3) }}>
                  <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: `${on * 100}%`, background: col }} />
                  <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: FONTS.mono, fontSize: 34 * u, color: on > 0.5 ? WHITE : GREY }}>{k + 1}</div>
                </div>
              );
            })}
          </div>
          <div style={{ display: "flex", gap }}>
            {segs.map((s, i) => {
              const w = s.n * blockW + (s.n - 1) * gap;
              const k = show(0.8 + i * 1.4 + s.n * 0.16, 0.5);
              const col = SEG[i % SEG.length];
              return (
                <div key={i} style={{ width: w, display: "flex", flexDirection: "column", alignItems: "center", gap: 12 * u, opacity: k, transform: `translateY(${(1 - k) * 16 * u}px)` }}>
                  <svg width={w} height={24 * u} viewBox={`0 0 ${w} ${24 * u}`}><path d={`M${4 * u} ${4 * u} V${14 * u} H${w - 4 * u} V${4 * u}`} fill="none" stroke={col} strokeWidth={3 * u} strokeLinecap="round" strokeLinejoin="round" /></svg>
                  <div style={{ fontFamily: FONTS.body, fontWeight: 700, fontSize: 28 * u, letterSpacing: "0.2em", textTransform: "uppercase", color: col, textAlign: "center" }}>{`${s.n} ${s.n === 1 ? "ano" : "anos"}${s.label ? " · " + s.label : ""}`}</div>
                </div>
              );
            })}
          </div>
        </div>
        {sub ? <div style={{ fontFamily: FONTS.display, fontWeight: 300, fontSize: 50 * u, color: GREY, textAlign: "center", maxWidth: 880 * u, opacity: show(0.8 + segs.length * 1.4) }}>{sub}</div> : null}
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
    </AbsoluteFill>
  );
};

export default LinhaTempoAnos;
